using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace ScreenDock {
 public partial class MainForm {
  List<Display> layoutOriginal=new List<Display>(),layoutPreview=new List<Display>();
  Dictionary<string,List<Native.Mode>> layoutModes=new Dictionary<string,List<Native.Mode>>();
  ComboBox layoutResolution=new ComboBox(),layoutRate=new ComboBox();ComboBox layoutOrientation=new ComboBox();Button layoutPrimary;Button layoutApply,layoutReset;Label layoutHint=new Label();bool layoutLoading,layoutDirty;string layoutSelected;
  Display LayoutCurrent {get{return Current==null?null:layoutPreview.Find(x=>x.Device==Current.Device);}}
  void AddInlineLayout(){
   LabelAt(this,"分辨率",300,402,70,28,13,false,Art.Muted);layoutResolution.SetBounds(375,400,210,32);layoutResolution.Font=Art.Font(14);layoutResolution.DropDownStyle=ComboBoxStyle.DropDownList;Controls.Add(layoutResolution);
   LabelAt(this,"刷新率",604,402,70,28,13,false,Art.Muted);layoutRate.SetBounds(675,400,130,32);layoutRate.Font=Art.Font(14);layoutRate.DropDownStyle=ComboBoxStyle.DropDownList;layoutRate.FormattingEnabled=true;layoutRate.Format+=delegate(object sender,ListControlConvertEventArgs e){e.Value=e.ListItem+" Hz";};Controls.Add(layoutRate);
   layoutApply=Button("应用更改",delegate{ApplyInlineLayout();});layoutApply.SetBounds(849,400,132,34);Controls.Add(layoutApply);
   layoutReset=Button("重置",delegate{layoutPreview=DisplayLayout.Copy(layoutOriginal);map.Displays=layoutPreview;layoutDirty=false;layoutSelected=null;layoutModes.Clear();ReloadInlineLayout();map.Invalidate();});layoutReset.SetBounds(995,400,139,34);Controls.Add(layoutReset);
   layoutHint.SetBounds(300,483,834,24);layoutHint.Font=Art.Font(12);layoutHint.ForeColor=Art.Muted;Controls.Add(layoutHint);
   LabelAt(this,"屏幕方向",300,446,75,28,13,false,Art.Muted);layoutOrientation.SetBounds(375,444,210,32);layoutOrientation.Font=Art.Font(14);layoutOrientation.DropDownStyle=ComboBoxStyle.DropDownList;layoutOrientation.Items.AddRange(new object[]{"横向","纵向（90°）","横向（翻转）","纵向（270°）"});Controls.Add(layoutOrientation);
   layoutPrimary=Button("设为主显示器",delegate{var d=LayoutCurrent;if(d==null||!d.Active)return;foreach(var item in layoutPreview)item.Primary=item==d;layoutDirty=true;UpdateInlineLayout();map.Invalidate();});layoutPrimary.SetBounds(849,444,285,34);Controls.Add(layoutPrimary);
   layoutOrientation.SelectedIndexChanged+=delegate{if(layoutLoading||layoutOrientation.SelectedIndex<0)return;var d=LayoutCurrent;if(d==null||!d.Active)return;uint orientation=(uint)layoutOrientation.SelectedIndex;var m=d.Mode;if((m.orientation%2)!=(orientation%2)){uint width=m.width;m.width=m.height;m.height=width;}m.orientation=orientation;d.Mode=m;layoutModes[d.Device]=layoutModes[d.Device].Select(mode=>{if((mode.orientation%2)!=(orientation%2)){uint width=mode.width;mode.width=mode.height;mode.height=width;}mode.orientation=orientation;return mode;}).ToList();DisplayLayout.Snap(d,layoutPreview);layoutDirty=true;layoutSelected=null;UpdateInlineLayout();map.Invalidate();};
   map.Changed=delegate{layoutDirty=true;UpdateInlineLayout();};
   layoutResolution.SelectedIndexChanged+=delegate{if(layoutLoading)return;var d=LayoutCurrent;if(d==null)return;layoutLoading=true;FillInlineRates(d.Mode.frequency);layoutLoading=false;InlineRateChanged();};layoutRate.SelectedIndexChanged+=delegate{if(!layoutLoading)InlineRateChanged();};
  }
  static bool SameLayout(List<Display> left,List<Display> right){return left.Count==right.Count&&left.All(a=>right.Any(b=>a.Identity==b.Identity&&a.Device==b.Device&&a.Active==b.Active&&a.Primary==b.Primary&&a.Mode.x==b.Mode.x&&a.Mode.y==b.Mode.y&&a.Mode.width==b.Mode.width&&a.Mode.height==b.Mode.height&&a.Mode.frequency==b.Mode.frequency&&a.Mode.orientation==b.Mode.orientation));}
  void ReloadInlineLayout(){bool changed=!SameLayout(layoutOriginal,displays);if(!layoutDirty||changed){layoutOriginal=DisplayLayout.Copy(displays);layoutPreview=DisplayLayout.Copy(displays);layoutDirty=false;layoutSelected=null;if(changed||layoutModes.Count==0){layoutModes.Clear();foreach(var d in displays.Where(x=>x.Active))layoutModes[d.Device]=demo?new List<Native.Mode>{d.Mode}:DisplayLayout.Modes(d);}}map.Displays=layoutPreview;UpdateInlineLayout();}
  void UpdateInlineLayout(){if(layoutApply==null)return;var d=LayoutCurrent;bool editable=d!=null&&d.Active&&!busy;map.DragEnabled=!busy;layoutApply.Enabled=layoutDirty&&PresetReady;layoutReset.Enabled=layoutDirty&&!busy;
   string selected=d==null?null:d.Device;if(layoutSelected!=selected||d==null){layoutSelected=selected;layoutLoading=true;layoutResolution.Items.Clear();layoutRate.Items.Clear();if(d!=null&&d.Active&&layoutModes.ContainsKey(d.Device)){foreach(var m in layoutModes[d.Device]){string name=m.width+" × "+m.height;if(!layoutResolution.Items.Contains(name))layoutResolution.Items.Add(name);}layoutResolution.SelectedItem=d.Mode.width+" × "+d.Mode.height;FillInlineRates(d.Mode.frequency);}layoutLoading=false;}
   layoutLoading=true;layoutOrientation.SelectedIndex=d==null?-1:(int)d.Mode.orientation;layoutLoading=false;layoutOrientation.Enabled=editable;layoutPrimary.Enabled=editable&&!d.Primary;layoutPrimary.Text=d!=null&&d.Primary?"主显示器（当前预览）":"设为主显示器";layoutResolution.Enabled=editable&&layoutResolution.Items.Count>0;layoutRate.Enabled=editable&&layoutRate.Items.Count>0;
   layoutHint.Text=layoutDirty?"有未应用的修改 · 点击“应用更改”生效，或“重置”撤销。":d!=null&&!d.Active?"请先启用此屏幕，再调整显示参数。":"拖动上方屏幕调整位置；修改分辨率或刷新率后点击“应用更改”。";
  }
  void FillInlineRates(uint preferred){layoutRate.Items.Clear();var d=LayoutCurrent;if(d==null||!layoutModes.ContainsKey(d.Device))return;foreach(var m in layoutModes[d.Device].Where(x=>x.width+" × "+x.height==(string)layoutResolution.SelectedItem))layoutRate.Items.Add(m.frequency);if(layoutRate.Items.Contains(preferred))layoutRate.SelectedItem=preferred;else if(layoutRate.Items.Count>0)layoutRate.SelectedIndex=0;}
  void InlineRateChanged(){var d=LayoutCurrent;if(d==null||layoutRate.SelectedItem==null)return;var m=layoutModes[d.Device].First(x=>x.width+" × "+x.height==(string)layoutResolution.SelectedItem&&x.frequency==(uint)layoutRate.SelectedItem);m.x=d.Mode.x;m.y=d.Mode.y;d.Mode=m;layoutDirty=true;map.Invalidate();UpdateInlineLayout();}
  void ApplyInlineLayout(){if(!PresetReady||!layoutDirty)return;Dictionary<string,Native.Mode> before=null;string beforePrimary=null;bool attempted=false;string message="";busy=true;SelectDisplay();
   try{var plan=DisplayLayout.Plan(layoutPreview);if(demo){message="演示布局验证通过，未修改真实屏幕。";return;}var fresh=Backend.Enumerate();if(!SameLayout(layoutOriginal,fresh))throw new Exception("屏幕状态已变化，请刷新设备后重新调整。");foreach(var pair in plan){var m=pair.Value;int code=Native.ChangeDisplaySettingsEx(pair.Key,ref m,IntPtr.Zero,2,IntPtr.Zero);if(code!=0)throw new Exception("驱动不支持所选显示模式（"+code+"），未应用。");}before=fresh.ToDictionary(d=>d.Device,d=>d.Active?d.Mode:Backend.Disabled(d.Mode));beforePrimary=fresh.Single(x=>x.Primary&&x.Active).Device;Backend.Remember(fresh);attempted=true;Backend.Apply(plan,layoutPreview.Single(x=>x.Primary&&x.Active).Device);using(var confirm=new Confirm("已修改屏幕位置和显示参数，是否保留？")){if(confirm.ShowDialog(this)!=DialogResult.OK){Backend.Apply(before,beforePrimary);attempted=false;message="已恢复原布局。";}else{attempted=false;message="已保留新的屏幕位置和显示参数。";}}layoutDirty=false;
   }catch(Exception ex){message=ex.Message;if(attempted&&before!=null)try{Backend.Apply(before,beforePrimary);message+=" 已恢复原布局。";}catch(Exception restore){message+=" 恢复失败，请使用 Windows 显示设置："+restore.Message;}MessageBox.Show(this,message,"显示设置");}
   finally{busy=false;RefreshDisplays();status.Text=message;}
  }
 }
}
